def test_v1_remote_yes():
    v1 = {"id": 1, "name": "Alice", "remote": "yes"}
    expected = {"id": 1, "title": "Alice", "work_mode": "remote", "version": 2}
    result = upgrade(v1)
    assert result == expected, f"Expected {expected}, got {result}"
    # Input must not be modified
    assert v1 == {"id": 1, "name": "Alice", "remote": "yes"}, "Input was modified!"

def test_v1_remote_no():
    v1 = {"id": 2, "name": "Bob", "remote": "no"}
    expected = {"id": 2, "title": "Bob", "work_mode": "office", "version": 2}
    result = upgrade(v1)
    assert result == expected

